import { expect, test } from '../fixtures';

// Starts from the bob session, not the default one.
test.use({ storageState: process.env.SOVA_AUTH_STATE_BOB! });

test('Email wrong old', async ({ page }) => {
  await test.step('Open the email settings', async () => {
    await page.goto('/user/settings/email');
  });

  await test.step('Type a wrong old email', async () => {
    await page.getByRole('textbox', { name: 'Old email address', exact: true }).fill('nobody@example.com');
  });

  await test.step('Type a new email', async () => {
    await page.getByRole('textbox', { name: 'New email address', exact: true }).fill('fresh@example.com');
  });

  await test.step('Repeat the new email', async () => {
    await page.getByRole('textbox', { name: 'Confirm email address', exact: true }).fill('fresh@example.com');
  });

  await test.step('Press Save', async () => {
    await page.getByRole('button', { name: 'Save', exact: true }).click();
  });

  await test.step('The error says the old email does not match [code]', async () => {
    await expect(page.locator('.invalid-feedback')).toContainText('Old email does not match');
  });
});
